const PAN_STORAGE_KEY = "hiker_postcard_pan_v1";
let savedPanMap = null;

function loadPanMap() {
  if (savedPanMap) return savedPanMap;
  try {
    savedPanMap = JSON.parse(localStorage.getItem(PAN_STORAGE_KEY) || "{}") || {};
  } catch {
    savedPanMap = {};
  }
  return savedPanMap;
}

export function normalizePhotoKey(url) {
  if (!url || typeof url !== "string") return "";
  const clean = url.split("?")[0].split("#")[0];
  const idx = clean.indexOf("assets/");
  return idx >= 0 ? clean.slice(idx) : clean.replace(/^\.\//, "");
}

export function getSavedPhotoPan(url) {
  const key = normalizePhotoKey(url);
  return key ? loadPanMap()[key] || null : null;
}

export function savePhotoPan(url, pctX, pctY) {
  const key = normalizePhotoKey(url);
  if (!key) return;
  const map = loadPanMap();
  map[key] = [Math.round(pctX * 10) / 10, Math.round(pctY * 10) / 10];
  try {
    localStorage.setItem(PAN_STORAGE_KEY, JSON.stringify(map));
  } catch {}
}

export function computeSmartPhotoCrop(url, imgW = 0, imgH = 0, boxRatio = 1.6) {
  const key = normalizePhotoKey(url);
  const meta = PHOTO_FOCUS_MAP[key];
  const imgRatio = imgW > 0 && imgH > 0 ? imgW / imgH : meta?.[4] || 1.5;
  const fx = meta ? meta[0] : 0.5;
  const fy = meta ? meta[1] : imgRatio < 1 ? 0.36 : 0.46;
  const safeTop = meta ? meta[2] : -1;
  const safeBot = meta ? meta[3] : -1;

  let pctX = 50;
  let pctY = 50;
  let x0 = 0,
    y0 = 0,
    winW = 1,
    winH = 1;

  if (imgRatio < boxRatio - 0.005) {
    winH = imgRatio / boxRatio;
    y0 = fy - winH * 0.46;
    if (safeTop >= 0 && safeBot > safeTop) {
      const pH = safeBot - safeTop;
      if (pH <= winH) {
        if (y0 > safeTop) y0 = safeTop;
        if (y0 + winH < safeBot) y0 = safeBot - winH;
      } else {
        y0 = safeTop;
      }
    }
    y0 = Math.max(0, Math.min(1 - winH, y0));
    pctY = (y0 / Math.max(1e-5, 1 - winH)) * 100;
  } else if (imgRatio > boxRatio + 0.005) {
    winW = boxRatio / imgRatio;
    x0 = Math.max(0, Math.min(1 - winW, fx - winW * 0.5));
    pctX = (x0 / Math.max(1e-5, 1 - winW)) * 100;
  }

  return {
    pctX: Math.max(0, Math.min(100, pctX)),
    pctY: Math.max(0, Math.min(100, pctY)),
    x0,
    y0,
    winW,
    winH,
    imgRatio,
    isPortrait: imgRatio < 0.94,
  };
}

export function applySmartPhotoPosition(imgEl, url, mediaBox = null) {
  if (!imgEl || !url) return { pctX: 50, pctY: 50, isPortrait: false };
  const key = normalizePhotoKey(url);
  const meta = PHOTO_FOCUS_MAP[key];
  const natW = imgEl.naturalWidth || 0;
  const natH = imgEl.naturalHeight || 0;
  const estRatio = natW > 0 && natH > 0 ? natW / natH : meta?.[4] || 1.5;
  const isPortrait = estRatio < 0.94;

  let boxRatio = 1.6;
  if (mediaBox) {
    mediaBox.classList.toggle("is-portrait-photo", isPortrait);
    boxRatio = isPortrait ? 1.24 : 1.6;
  }

  const saved = getSavedPhotoPan(url);
  if (saved) {
    imgEl.style.objectPosition = `${saved[0]}% ${saved[1]}%`;
    imgEl.dataset.panX = String(saved[0]);
    imgEl.dataset.panY = String(saved[1]);
    return { pctX: saved[0], pctY: saved[1], isPortrait };
  }

  const crop = computeSmartPhotoCrop(url, natW, natH, boxRatio);
  const rx = Math.round(crop.pctX * 10) / 10;
  const ry = Math.round(crop.pctY * 10) / 10;
  imgEl.style.objectPosition = `${rx}% ${ry}%`;
  imgEl.dataset.panX = String(rx);
  imgEl.dataset.panY = String(ry);
  return crop;
}